        return TableOpPhaseChanged(PhaseChangedNoticePayloadTablePhase.fromWire(body));
      case 'TurnChanged':
        return TableOpTurnChanged(TurnChangedNoticePayloadInt.fromWire(body));
      case 'RoundStarted':
        return TableOpRoundStarted(RoundStartedNoticePayload.fromWire(body));
      case 'RoundEnded':
        return TableOpRoundEnded(RoundEndedNoticePayloadRoundSummary.fromWire(body));
    }
    throw FormatException('unknown TableOp variant: $name');
  }
}

