enum TablePhase {
  seating('Seating'),
  dealing('Dealing'),
  playing('Playing'),
  scoring('Scoring'),
  finished('Finished');

  const TablePhase(this.wireName);
  final String wireName;

  Object? toWire({bool named = false}) => wireName;

  static TablePhase fromWire(Object? wire) =>
      values.firstWhere((v) => v.wireName == wire as String,
          orElse: () => throw FormatException('unknown TablePhase variant: $wire'));
}

